"""SQLite-backed translation memory storage.

Schema:
    segments(id INTEGER PRIMARY KEY, source TEXT, target TEXT, source_norm TEXT)
    trigrams(seg_id INTEGER, trigram TEXT)   -- inverted index for prefiltering

`source_norm` stores the normalized form of `source` (see `normalize`) so that
fuzzy lookup can operate on canonical text without re-normalizing every row.
"""

from __future__ import annotations

import re
import sqlite3
from typing import Iterable, Iterator

DEFAULT_DB_PATH = "tm.db"

# Casefold -> remove punctuation -> collapse whitespace.
_PUNCT_RE = re.compile(r"[^\w\s]+", re.UNICODE)


def normalize(text: str) -> str:
    """Normalize text for matching: casefold, strip punctuation, collapse whitespace."""
    t = text.casefold()
    t = _PUNCT_RE.sub("", t)
    return " ".join(t.split())


def trigrams(s: str) -> set[str]:
    """Set of 3-grams of an already-normalized string (empty if len < 3)."""
    if len(s) < 3:
        return set()
    return {s[i : i + 3] for i in range(len(s) - 2)}


def connect(path: str = DEFAULT_DB_PATH) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def init_db(conn: sqlite3.Connection) -> None:
    conn.executescript(
        """
        CREATE TABLE IF NOT EXISTS segments (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            source      TEXT NOT NULL,
            target      TEXT NOT NULL,
            source_norm TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS trigrams (
            seg_id  INTEGER NOT NULL REFERENCES segments(id) ON DELETE CASCADE,
            trigram TEXT NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_trigrams_trigram ON trigrams(trigram, seg_id);
        CREATE INDEX IF NOT EXISTS idx_segments_source_norm ON segments(source_norm);
        """
    )
    conn.commit()


def add(conn: sqlite3.Connection, source: str, target: str) -> int:
    """Insert one segment pair; returns its id."""
    source_norm = normalize(source)
    cur = conn.execute(
        "INSERT INTO segments (source, target, source_norm) VALUES (?, ?, ?)",
        (source, target, source_norm),
    )
    seg_id = cur.lastrowid
    conn.executemany(
        "INSERT INTO trigrams (seg_id, trigram) VALUES (?, ?)",
        [(seg_id, g) for g in trigrams(source_norm)],
    )
    conn.commit()
    return seg_id


def import_tsv(conn: sqlite3.Connection, path: str) -> int:
    """Import a two-column TSV file (source<TAB>target per line).

    A header line whose columns are literally 'source'/'target' is skipped.
    Blank or malformed lines are skipped. Returns the number of rows added.
    """
    rows: list[tuple[str, str]] = []
    with open(path, "r", encoding="utf-8") as fh:
        for lineno, line in enumerate(fh):
            line = line.rstrip("\n").rstrip("\r")
            if not line.strip():
                continue
            parts = line.split("\t")
            if len(parts) < 2:
                print(f"tm.import_tsv: skipping malformed line {lineno + 1}", file=__import__("sys").stderr)
                continue
            src, tgt = parts[0].strip(), parts[1].strip()
            if lineno == 0 and [src.casefold(), tgt.casefold()] == ["source", "target"]:
                continue
            rows.append((src, tgt))
    return add_many(conn, rows)


def add_many(conn: sqlite3.Connection, pairs: Iterable[tuple[str, str]]) -> int:
    """Bulk insert of (source, target) pairs; returns the number added."""
    data = []
    tri_data = []
    base = conn.execute("SELECT COALESCE(MAX(id), 0) FROM segments").fetchone()[0]
    for i, (source, target) in enumerate(pairs, start=1):
        norm = normalize(source)
        seg_id = base + i
        data.append((seg_id, source, target, norm))
        for g in trigrams(norm):
            tri_data.append((seg_id, g))
    conn.executemany(
        "INSERT INTO segments (id, source, target, source_norm) VALUES (?, ?, ?, ?)",
        data,
    )
    conn.executemany(
        "INSERT INTO trigrams (seg_id, trigram) VALUES (?, ?)", tri_data
    )
    conn.commit()
    return len(data)


def iter_segments(conn: sqlite3.Connection) -> Iterator[tuple[int, str, str, str]]:
    """Yield (id, source, target, source_norm) for every stored pair."""
    yield from conn.execute("SELECT id, source, target, source_norm FROM segments")


def count(conn: sqlite3.Connection) -> int:
    return conn.execute("SELECT COUNT(*) FROM segments").fetchone()[0]

