        return 0
    la, lb = len(a), len(b)
    if la == 0:
        return lb if cutoff is None or lb <= cutoff else cutoff + 1
    if lb == 0:
        return la if cutoff is None or la <= cutoff else cutoff + 1
    if cutoff is not None and abs(la - lb) > cutoff:
        return cutoff + 1
    if _rf_Levenshtein is not None:
        d = _rf_Levenshtein.distance(a, b, score_cutoff=cutoff)
        # rapidfuzz returns score_cutoff + 1 when the distance exceeds it.
        return d
    return _levenshtein_py(a, b, la, lb, cutoff)


def _levenshtein_py(a: str, b: str, la: int, lb: int, cutoff: int | None) -> int:
    if lb > la:
        a, b, la, lb = b, a, lb, la

