def levenshtein(a: str, b: str, cutoff: int | None = None) -> int:
    """Edit distance between two strings.

    If `cutoff` is given and the true distance exceeds it, returns cutoff + 1
    (early-abandoned banded DP). Never returns a value > cutoff + 1.
    """
    if a == b:
        return 0
    la, lb = len(a), len(b)
    if la == 0:
        return lb if cutoff is None or lb <= cutoff else cutoff + 1
    if lb == 0:
        return la if cutoff is None or la <= cutoff else cutoff + 1
    if cutoff is not None and abs(la - lb) > cutoff:
        return cutoff + 1
    if lb > la:
        a, b, la, lb = b, a, lb, la
